REPS = [('    def do_OPTIONS(self):\n        if self.path.startswith("/cpapi/"):', '    def do_OPTIONS(self):\n        if self.path.startswith("/__rtc/"): return self.rtc()\n        if self.path.startswith("/cpapi/"):'), ('    def do_POST(self):\n        self.api() if self.path.startswith("/cpapi/") else self.proxy()\n\n', '    def do_POST(self):\n        if self.path.startswith("/__rtc/"): return self.rtc()\n        self.api() if self.path.startswith("/cpapi/") else self.proxy()\n\n    def do_PATCH(self):\n        return self.rtc() if self.path.startswith("/__rtc/") else self.deny(405, "Không hỗ trợ.")\n\n    def do_DELETE(self):\n        return self.rtc() if self.path.startswith("/__rtc/") else self.deny(405, "Không hỗ trợ.")\n\n    # ---------- Hình kiểu Parsec (WebRTC): /__rtc/<cổng máy>/whep → MediaMTX nội bộ (phathinh.py) ----------\n    def rtc(self):\n        try:\n            self._rtc()\n        except (BrokenPipeError, ConnectionResetError):\n            pass\n        except Exception as e:\n            log("rtc lỗi:", repr(e))\n            try: self.deny(502, "Hình kiểu mới chưa sẵn sàng.")\n            except Exception: pass\n\n    def _rtc(self):\n        m = re.match(r"^/__rtc/(\\d{4,5})/(whep(?:/[A-Za-z0-9_-]{1,80})?)$", urllib.parse.urlparse(self.path).path)\n        if not m or RTC_OFF: return self.deny(404, "Không có.")\n        if self.command == "OPTIONS":\n            self.send_response(204); self.send_header("Allow", "POST, PATCH, DELETE, OPTIONS"); self.send_header("Content-Length", "0"); self.end_headers(); return\n        origin = self.headers.get("Origin", "")\n        if origin and origin not in SELF_ORIGINS: return self.deny(403, "Nguồn không được phép.")\n        auth = self.cookie_auth()\n        if not auth: return self.deny(401, "Hãy mở máy từ trang blueroblox.shop.")\n        port = int(m.group(1))\n        if not auth.get("a"):\n            if maint().get("maint"): return self.deny(503, "Đang bảo trì.")\n            if auth.get("u") not in port_owners(port): return self.deny(403, "Đây không phải máy của bạn.")\n        name = rtc_name(port)\n        if not name: return self.deny(404, "Không thấy máy.")\n        data = self.body(200000) if self.command in ("POST", "PATCH") else None\n        hdr = {"Content-Type": self.headers.get("Content-Type") or "application/sdp"}\n        if self.headers.get("If-Match"): hdr["If-Match"] = self.headers["If-Match"]\n        c = http.client.HTTPConnection("127.0.0.1", RTC_HTTP, timeout=25)\n        try:\n            c.request(self.command, f"/{name}/{m.group(2)}", body=data, headers=hdr)\n            r = c.getresponse(); body = r.read()\n        except OSError:\n            return self.deny(503, "Hình kiểu mới chưa chạy.")\n        finally:\n            c.close()\n        self.send_response(r.status, r.reason)\n        for k in ("Content-Type", "ETag", "Accept-Patch"):\n            if r.getheader(k): self.send_header(k, r.getheader(k))\n        loc = r.getheader("Location")\n        if loc:\n            sid = loc.rstrip("/").rsplit("/", 1)[-1]\n            self.send_header("Location", f"/__rtc/{port}/whep/{sid}")\n        self.send_header("Cache-Control", "no-store")\n        self.send_header("Content-Length", str(len(body)))\n        self.end_headers()\n        self.wfile.write(body)\n\n'), ('def port_owners(port):', 'RTC_OFF = CFG.get("RTC", "1") == "0" or os.name != "nt"\nRTC_HTTP = int(CFG.get("RTC_HTTP_PORT") or 8889)\n_rcache = {}\ndef rtc_name(port):\n    """cổng adb → tên máy (= tên cửa sổ LDPlayer) để phathinh.py quay đúng cửa sổ."""\n    now = time.time(); c = _rcache.get(port)\n    if c and c[1] > now: return c[0]\n    name = None\n    try:\n        for p in json.load(open(os.path.expanduser("~/redroid/phones.json"), encoding="utf-8")).get("phones", []):\n            if int(p.get("port") or 0) == int(port): name = p.get("name")\n    except Exception: pass\n    if not name:\n        rows = [r for r in (sb_get(f"/rest/v1/cloud_phones?port=eq.{int(port)}&status=eq.active&select=container,node") or []) if on_node(r)]\n        name = rows[0].get("container") if rows else None\n    if name and not re.match(r"^[A-Za-z0-9_.-]{1,60}$", name): name = None\n    _rcache[port] = (name, now + 30)\n    return name\n\n\ndef port_owners(port):'), ('  post({ t: "boot" });\\n})();\\n\'.encode()', '  // ===== HÌNH KIỂU PARSEC (WebRTC qua UDP, nén bằng card NVIDIA trên máy chủ) =====\\n  //  Có hình mới → che hình cũ (canvas), chạm/phím vẫn đi đường cũ. Không nối được / đứng hình → tự về hình cũ, lát sau thử lại.\\n  //  Tắt: thêm cprtc=0 vào địa chỉ.\\n  (function () {\\n    if (H.get("cprtc") === "0" || !window.RTCPeerConnection || !window.fetch) return;\\n    var mm = /127\\\\.0\\\\.0\\\\.1:(\\\\d{4,5})$/.exec(H.get("udid") || ""); if (!mm) return;\\n    var PORT = mm[1], pc = null, vid = null, on = false, fails = 0, wd = null, lastT = -1, still = 0, res = null;\\n    function css(el, st) { for (var k in st) el.style.setProperty(k, st[k], "important"); }\\n    function canvas(show) { var cv = document.querySelector(".video-layer"); if (cv) cv.style.setProperty("visibility", show ? "visible" : "hidden", "important"); }\\n    function stop(why) {\\n      clearInterval(wd); wd = null;\\n      try { if (res) fetch(res, { method: "DELETE", credentials: "include" }); } catch (e) {}\\n      res = null; try { if (pc) pc.close(); } catch (e) {} pc = null;\\n      if (vid && vid.parentNode) vid.parentNode.removeChild(vid); vid = null;\\n      canvas(true);\\n      if (on) post({ t: "rtc", on: 0, why: why });\\n      on = false;\\n      if (why === "bye") return;\\n      fails++; setTimeout(start, Math.min(60000, 4000 * fails * fails));     // thử lại: 4s, 16s, 36s, 60s…\\n    }\\n    function start() {\\n      if (pc || document.hidden) { if (!pc) setTimeout(start, 3000); return; }\\n      var box = document.querySelector(".video"), tl = document.querySelector(".touch-layer");\\n      if (!box || !tl || !okSent) return setTimeout(start, 500);             // đợi hình cũ lên trước (để biết khung, chạm đúng chỗ)\\n      pc = new RTCPeerConnection({ iceServers: [{ urls: "stun:stun.l.google.com:19302" }, { urls: "stun:stun.cloudflare.com:3478" }], bundlePolicy: "max-bundle" });\\n      pc.addTransceiver("video", { direction: "recvonly" });\\n      vid = document.createElement("video"); vid.muted = true; vid.autoplay = true; vid.playsInline = true;\\n      vid.setAttribute("playsinline", ""); vid.setAttribute("muted", ""); vid.disablePictureInPicture = true;\\n      css(vid, { position: "absolute", left: "0", top: "0", width: "100%", height: "100%", "object-fit": "fill", "pointer-events": "none", background: "transparent", margin: "0" });\\n      box.insertBefore(vid, tl);\\n      pc.ontrack = function (e) {\\n        try { e.receiver.playoutDelayHint = 0; } catch (x) {}\\n        try { e.receiver.jitterBufferTarget = 0; } catch (x) {}\\n        vid.srcObject = (e.streams && e.streams[0]) || new MediaStream([e.track]);\\n        var pl = vid.play(); if (pl && pl.catch) pl.catch(function () {});\\n      };\\n      pc.onconnectionstatechange = function () { if (pc && (pc.connectionState === "failed" || pc.connectionState === "closed")) stop("net"); };\\n      var t0 = Date.now(); lastT = -1; still = 0;\\n      wd = setInterval(function () {                                         // canh: có khung mới thật mới che hình cũ; đứng > 2,5s → về hình cũ\\n        if (!vid) return;\\n        var t = vid.currentTime;\\n        if (t > 0 && t !== lastT) {\\n          lastT = t; still = 0;\\n          if (!on) { on = true; fails = 0; canvas(false); post({ t: "rtc", on: 1, ms: Date.now() - t0 }); }\\n        } else if (on) { if (++still > 10) stop("still"); }\\n        else if (Date.now() - t0 > 15000) stop("timeout");\\n      }, 250);\\n      pc.createOffer().then(function (o) { return pc.setLocalDescription(o); }).then(function () {\\n        return new Promise(function (ok) {                                    // gom địa chỉ mạng tối đa 1,2 giây rồi gửi 1 lần\\n          if (pc.iceGatheringState === "complete") return ok();\\n          var tm = setTimeout(ok, 1200);\\n          pc.addEventListener("icegatheringstatechange", function () { if (pc && pc.iceGatheringState === "complete") { clearTimeout(tm); ok(); } });\\n        });\\n      }).then(function () {\\n        return fetch("/__rtc/" + PORT + "/whep", { method: "POST", credentials: "include", headers: { "Content-Type": "application/sdp" }, body: pc.localDescription.sdp });\\n      }).then(function (r) {\\n        if (r.status !== 201 && r.status !== 200) throw new Error("whep " + r.status);\\n        var l = r.headers.get("Location"); if (l) res = l;\\n        return r.text();\\n      }).then(function (sdp) { if (pc) return pc.setRemoteDescription({ type: "answer", sdp: sdp }); })\\n        .catch(function (e) { if (pc) stop("neg:" + (e && e.message)); });\\n    }\\n    // trình duyệt / app chặn tự phát video → chạm lần đầu là phát\\n    addEventListener("pointerdown", function () { if (vid && vid.paused) { var p = vid.play(); if (p && p.catch) p.catch(function () {}); } }, true);\\n    addEventListener("touchstart", function () { if (vid && vid.paused) { var p = vid.play(); if (p && p.catch) p.catch(function () {}); } }, true);\\n    document.addEventListener("visibilitychange", function () { if (document.hidden && pc) { stop("bye"); } else if (!document.hidden && !pc) { fails = 0; setTimeout(start, 300); } });\\n    addEventListener("pagehide", function () { if (pc) stop("bye"); });\\n    setTimeout(start, 300);\\n  })();\\n  post({ t: "boot" });\\n})();\\n\'.encode()'), ('inject.js?v=10', 'inject.js?v=11')]
for i, (a, b) in enumerate(REPS):
    if s.count(a) != 1: sys.exit(f"KHÔNG vá được (chỗ số {i + 1}) — cpapi.py trên máy khác bản dự kiến. Chưa đổi gì. Gửi dòng này cho hỗ trợ.")
